  cwd: path.resolve("/home/isourxbh/autoa11y"),
  enableReadFiles: true,
  enableEditor: true,
  enableApplyPatch: true,
  enableSearch: false,
  enableBash: false,
  enableWebFetch: false,
  enableSkills: false,
  enableAskQuestion: false,
  enableSubmitAndExit: false,
});
const names = tools.map((t) => t.name);
console.log("builtin tool names:", names.join(", "));

// 5. read_files can read the demo HTML
