import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const providersPath = path.join(os.homedir(), ".cline", "data", "settings", "providers.json");
const data = JSON.parse(fs.readFileSync(providersPath, "utf8"));

for (const [name, pv] of Object.entries(data.providers)) {
  const auth = pv.settings?.auth;
  if (!auth?.accessToken) continue;
  const now = Date.now();
  const exp = typeof auth.expiresAt === "number" ? auth.expiresAt : Number(auth.expiresAt) || 0;
  console.log(`provider=${name} model=${pv.settings?.model ?? "(none)"}`);
  console.log(`  token prefix=${auth.accessToken.slice(0, 14)}...`);
  console.log(`  expiresAt=${exp} now=${now} expired=${exp > 0 && exp < now} (${exp ? new Date(exp).toISOString() : "n/a"})`);
}

// Test the gateway with the cline-pass token.
const target = data.providers["cline-pass"] ?? data.providers["cline"];
const token = target.settings.auth.accessToken;
const base = "https://api.cline.bot/api/v1";

// 1. list models (lightweight)
const modelsRes = await fetch(`${base}/models`, {
  headers: { Authorization: `Bearer ${token}` },
});
console.log(`\nGET /models -> HTTP ${modelsRes.status}`);
const body = await modelsRes.text();
console.log("  body head:", body.slice(0, 300));

// 2. minimal chat completion
