  method: "POST",
  headers: {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: target.settings.model ?? "cline-pass/deepseek-v4-pro",
    messages: [{ role: "user", content: "Reply with exactly: pong" }],
    max_tokens: 16,
    stream: false,
  }),
});
console.log(`\nPOST /chat/completions -> HTTP ${chatRes.status}`);
console.log("  body head:", (await chatRes.text()).slice(0, 500));

