      return null;
    }

    return {
      providerId: "cline-pass",
      modelId,
      apiKey: valid.access,
      baseUrl: "https://api.cline.bot/api/v1",
    };
  } catch (err) {
    console.warn("Failed to validate Cline credentials:", err.message);
    return null;
  }
}

