import { chromium } from "playwright";

const url = "http://localhost:5173/";
const browser = await chromium.launch();
const page = await browser.newPage();
page.setDefaultTimeout(150000);

const consoleErrors = [];
const pageErrors = [];
page.on("console", (m) => m.type() === "error" && consoleErrors.push(m.text()));
page.on("pageerror", (e) => pageErrors.push(e.message));

await page.goto(url, { waitUntil: "networkidle" });
await page.waitForTimeout(1000);

// --- initial state ---
const noDiffInitial = await page.getByText("No diff yet").count();
const notRunBadge = await page.getByText("Not run yet").count();
console.log("initial: noDiff placeholder =", noDiffInitial, "| 'Not run yet' badge =", notRunBadge);

// --- click run ---
await page.getByRole("button", { name: /Run AutoA11y Fixer/ }).click();

// Wait for the button to enter running state (spinner) then for completion badge.
await page.getByText("Running").waitFor({ timeout: 15000 }).catch(() => {});
console.log("button clicked (running state seen)");

await page.getByText("All fixed").waitFor({ timeout: 150000 });
console.log("completion badge 'All fixed' appeared");

// --- final state ---
const statCounts = await page.locator(".text-4xl").allTextContents();
console.log("stat card numbers:", statCounts);

const noDiffFinal = await page.getByText("No diff yet").count();
const beforeTitle = await page.getByText("Before (4 violations)").count();
const afterTitle = await page.getByText("After (0 violations)").count();
const removedLine = await page.locator("text=#cccccc").count();
console.log("final: noDiff placeholder =", noDiffFinal);
console.log("leftTitle 'Before (4 violations)' =", beforeTitle);
console.log("rightTitle 'After (0 violations)' =", afterTitle);
console.log("removed line #cccccc present in diff =", removedLine);

console.log("console errors:", consoleErrors.length);
console.log("page errors:", pageErrors.length);
if (consoleErrors.length) console.log("CONSOLE ERRORS:", consoleErrors.slice(0, 5));
if (pageErrors.length) console.log("PAGE ERRORS:", pageErrors.slice(0, 5));

await page.screenshot({ path: "/tmp/autoa11y-e2e.png", fullPage: true });
console.log("screenshot -> /tmp/autoa11y-e2e.png");

await browser.close();
